CREATE TABLE IF NOT EXISTS nfr(id TEXT PRIMARY KEY,attribute TEXT,requirement TEXT,mechanism TEXT,target TEXT,verification TEXT,traces TEXT);
INSERT OR IGNORE INTO nfr VALUES
('NFR-01','Scalability','Each service scales independently; peak OPD hours must not require scaling the whole platform.','One container per service, stateless (FR-INT-07), gateway load balancing (FR-GWY-06), Kubernetes HPA.','Proposed: 10,000 concurrent users; 2x load with <20% latency growth','Load test (k6) per service; autoscale drill','Report s4; FR-GWY-06; FR-INT-07'),
('NFR-02','Security','All traffic encrypted and authenticated; least-privilege by role; no public internal services.','TLS 1.2+, OAuth2/ABHA tokens at gateway (FR-GWY-03/04), service tokens, Vault secrets, only gateway exposed.','Proposed: 0 critical findings in pen-test; 100% endpoints behind auth','OWASP ZAP/pen-test, dependency scans in CI','FR-GWY-03/04/11; FR-COM-01; FR-INT-01'),
('NFR-03','Privacy & Consent','No patient data is read or shared without valid, purpose-limited, revocable consent.','Consent check on every access (FR-CON-05); revoke takes effect immediately; break-glass needs reason + audit (FR-CON-08); de-identified analytics (FR-ANA-03).','Proposed: 100% reads consent-checked; revoke effective <1s','Automated negative tests: access after revoke must fail','FR-CON-01..08; FR-LON-03; FR-DOC-07; FR-EXT-10; DPDP Act, ABDM policy'),
('NFR-04','Availability','One service failing must not stop the platform; no single point of failure.','Independent services, 2+ gateway instances, health checks, queue buffering when consumers are down, timeouts/fallback to last-known history.','Proposed: 99.9% monthly (core), 99.5% (AI services)','Chaos tests (kill a pod); uptime monitoring','Report s4, s15; FR-GWY-06; FR-INT-05'),
('NFR-05','Performance','Fast, mobile-friendly screens; slow work is asynchronous.','REST for immediate reads; OCR, record building, notifications via event bus; indexes (abha_id, created_at); caching of record_summary.','Proposed: p95 <500 ms reads, <1 s writes; OCR progress shown, not blocking','Latency SLOs in Prometheus/Grafana; load tests','FR-DOC-04; FR-LON-05; FR-LPR-02'),
('NFR-06','Data Ownership & Integrity','Each service owns its database; combined history never built by cross-DB joins.','Database per service (FR-DOM-01/FR-INT-07); Longitudinal service is an index only (FR-LON-01); outbox pattern; locked encounters + logged addendum (FR-ENC-06).','Proposed: 0 cross-service DB connections; 0 lost events','Schema/network policy review; event replay test','FR-DOM-01; FR-LON-01; FR-ENC-06; FR-LPR-09'),
('NFR-07','Consistency (Eventual)','Combined history may lag the source; must be visible and recoverable.','Idempotent consumers, retries, dead-letter queue, append-only event log with rebuild by replay, last-updated shown in UI.','Proposed: projection lag p95 <5 s','Inject duplicate/out-of-order events; replay test','Report s6, s15; FR-EXT-09; FR-LPR-02'),
('NFR-08','Interoperability','ABDM-compatible, standard codes and FHIR R4 exchange.','ABDM/ABHA service (HIP/HIU), Terminology service (NAMASTE, ICD-11 TM2), FHIR mapper, versioned OpenAPI.','Proposed: pass ABDM sandbox certification; 100% coded diagnoses validated','ABDM sandbox tests; FHIR validator in CI','FR-ABD-01..11; FR-TER-01..09; FR-INT-06'),
('NFR-09','Safety & Explainability','AI only assists; no automatic prescribing; every suggestion has reasons and practitioner review.','Draft status on AI output (FR-AI-05), accept/edit/reject (FR-AI-07), safety check before save, overrides need reason (FR-SAF-04), model registry.','Proposed: 100% AI items practitioner-reviewed; 100% overrides audited','Clinical review of rules; audit queries','FR-AI-05/07; FR-SAF-01..05; FR-RED-01..06'),
('NFR-10','Auditability & Observability','Every access and change is traceable; operations are monitored.','Correlation ID on every request (FR-GWY-09), append-only tamper-proof audit (FR-AUD-05), patient can see who accessed (FR-AUD-07), Prometheus/Grafana/ELK, alerts.','Proposed: 100% access events logged; audit retention per policy (e.g. 7 yrs)','Audit completeness test; log-tamper test','FR-AUD-01..09; FR-COM-03; FR-INT-05'),
('NFR-11','Maintainability & Deployability','Services build, test and deploy independently with a shared template.','Per-service repo + CI/CD, Docker, Helm/Argo CD canary, auto rollback, config outside code (FR-INT-04).','Proposed: deploy any service in <30 min with zero downtime','Pipeline metrics (lead time, rollback time)','Report s12; FR-INT-04'),
('NFR-12','Usability & Localisation','Simple for practitioners and patients; multilingual; same behaviour across AYUSH screens.','Shared module structure, bilingual terms (FR-DOM-08), Indian-language templates and UI (FR-NOT-06, FR-TER-08), accessible mobile UI.','Proposed: new practitioner records a visit in <5 min after training; WCAG 2.1 AA','Usability tests with practitioners of each system','FR-DOM-08; FR-NOT-06; FR-AI-01');
